// HMAC-SHA256 signature verification, opt-in.
// Enable by setting LEAD_FORM_SIGNING_SECRET in your n8n env
// AND configuring the same secret in your form provider.
// Pass-through when unset.

const secret = $env.LEAD_FORM_SIGNING_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

if (!secret || !integrityCheckEnabled) {
  // Disabled by design, let the request through.
  return [$input.first()];
}

const crypto = require('crypto');
const item = $input.first();
const rawBody = item.json.rawBody || (typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body || {}));
const providedSig = item.json.headers && (item.json.headers['x-form-signature'] || item.json.headers['X-Form-Signature']);

if (!providedSig) {
  throw new Error('UNAUTHORIZED: missing x-form-signature header');
}

const expected = crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

// Length-guard before constant-time compare. Without this, a 1-char
// signature throws RangeError = free DoS on the verifier.
if (providedSig.length !== expected.length) {
  throw new Error('UNAUTHORIZED: signature length mismatch');
}

const expectedBuf = Buffer.from(expected, 'utf8');
const providedBuf = Buffer.from(providedSig, 'utf8');

if (!crypto.timingSafeEqual(expectedBuf, providedBuf)) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [$input.first()];

// Per-IP sliding-window rate limit, opt-in.
// Enable by setting RATE_LIMIT_ENABLED=1 in your n8n env.
// 60 requests per 5 minutes per IP. Adjust below.
//
// For real production loads put rate limiting on a reverse proxy
// (Nginx limit_req_zone, Cloudflare WAF, Traefik). This node is
// defense-in-depth, not the primary control.
//
// $getWorkflowStaticData is per-instance and not cluster-aware.
// Multi-worker n8n: replace with Redis INCR + EXPIRE (snippet below).

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return [$input.first()];
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const ip = (item.json.headers && (item.json.headers['x-forwarded-for'] || item.json.headers['x-real-ip'])) || 'unknown';
const key = String(ip).split(',')[0].trim();

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

// Evict expired entries
for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
// Cap map size
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a,b) => (a[1][0]||0) - (b[1][0]||0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' requests per ' + Math.round(WINDOW_MS / 60000) + ' minutes for ' + key);
}
buckets[key] = [...hits, now];

return [$input.first()];

// Redis variant for clustered n8n:
// const Redis = require('ioredis');
// const redis = new Redis(process.env.REDIS_URL);
// const cnt = await redis.incr('rl:' + key);
// if (cnt === 1) await redis.expire('rl:' + key, 300);
// await redis.quit();
// if (cnt > LIMIT) throw new Error('RATE_LIMIT_EXCEEDED');

// 5-minute idempotency window on form submission ID, opt-in.
// Enable by setting IDEMPOTENCY_ENABLED=1.
// Form providers retry on 5xx. Without dedup we create the lead twice in CRM.
//
// Replace the in-memory block with Redis SET NX EX 300 for clustered n8n.

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return [$input.first()];
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 10000;

const item = $input.first();
const body = item.json.body || {};
// Idempotency key: provider-supplied submission ID, fallback to email + minute-bucketed timestamp
const submissionId = body.submission_id || body.id;
const email = (body.email || '').toLowerCase();
const minuteBucket = Math.floor(Date.now() / 60000);
const idempotencyKey = submissionId || (email && (email + ':' + minuteBucket));

if (!idempotencyKey) {
  // No deduplicable key, let it through
  return [$input.first()];
}

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

// Evict expired
for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
// Cap size
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a,b) => a[1] - b[1]).slice(0, 1000);
  for (const [k] of oldest) delete seen[k];
}

if (seen[idempotencyKey]) {
  // Duplicate detected. Emit a sentinel item that the
  // 'Skip If Duplicate' IF node routes to 'Respond Duplicate'
  // (200 OK + { deduped: true }). Without that 200 the source
  // provider would hold the HTTP connection until n8n's webhook
  // timeout (default 30s) and mark delivery failed.
  return [{ json: { skipped: true, reason: 'duplicate', dedupKey: String(idempotencyKey) } }];
}
seen[idempotencyKey] = now;

return [$input.first()];

// Redis variant:
// const result = await redis.set('idem:' + idempotencyKey, '1', 'EX', 300, 'NX');
// if (result === null) return [];

// Normalize the form payload into a stable schema regardless of provider
// (Webflow / Tally / Typeform / custom HTML). Map common field names.

const body = ($input.first().json.body || {});

const pick = (...keys) => {
  for (const k of keys) {
    if (body[k] != null && String(body[k]).trim() !== '') return String(body[k]).trim();
  }
  return null;
};

const submissionId = pick('submission_id', 'id', 'submissionId') || ('lead-' + Date.now());
const email = (pick('email', 'email_address', 'EmailAddress') || '').toLowerCase();
const name = pick('name', 'full_name', 'fullName', 'first_name') || 'Unknown';
const company = pick('company', 'organization', 'company_name', 'org') || null;
const phone = pick('phone', 'phoneNumber', 'phone_number') || null;

// BANT-aligned input fields. Form-provider-specific names mapped here.
const budget = pick('budget', 'budget_range', 'monthly_budget') || null;
const authority = pick('authority', 'role', 'job_title', 'title') || null;
const need = pick('need', 'pain_point', 'problem', 'use_case') || null;
const timeline = pick('timeline', 'when', 'urgency', 'start_date') || null;
const intent = pick('intent', 'reason', 'message', 'notes') || null;
const source = pick('source', 'utm_source', 'referrer') || 'direct';

return [{
  json: {
    submissionId,
    email,
    name,
    company,
    phone,
    bant: { budget, authority, need, timeline, intent },
    source,
    receivedAt: new Date().toISOString(),
  },
}];

// BANT scoring: 0-100 score from Budget / Authority / Need / Timeline + Intent.
// Each filled-out BANT field is worth 20 points. Intent is worth 20.
// Override the rubric below for your sales motion.

const input = $input.first().json;
const { bant } = input;

let score = 0;
const reasons = [];

// Budget signal
if (bant.budget) {
  const b = String(bant.budget).toLowerCase();
  if (b.includes('10k') || b.includes('25k') || b.includes('50k') || b.includes('100k') || b.includes('enterprise')) {
    score += 25;
    reasons.push('high-budget');
  } else if (b.includes('5k') || b.includes('1k') || b.includes('mid')) {
    score += 15;
    reasons.push('mid-budget');
  } else {
    score += 8;
    reasons.push('budget-disclosed');
  }
}

// Authority signal
if (bant.authority) {
  const a = String(bant.authority).toLowerCase();
  if (a.includes('ceo') || a.includes('founder') || a.includes('vp') || a.includes('director') || a.includes('head')) {
    score += 25;
    reasons.push('decision-maker');
  } else if (a.includes('manager') || a.includes('lead')) {
    score += 15;
    reasons.push('influencer');
  } else {
    score += 8;
    reasons.push('individual-contributor');
  }
}

// Need signal (free-text length proxy)
if (bant.need) {
  const len = String(bant.need).length;
  if (len > 100) { score += 20; reasons.push('detailed-need'); }
  else if (len > 30) { score += 12; reasons.push('clear-need'); }
  else { score += 6; reasons.push('vague-need'); }
}

// Timeline signal
if (bant.timeline) {
  const t = String(bant.timeline).toLowerCase();
  if (t.includes('immediate') || t.includes('now') || t.includes('this month') || t.includes('week')) {
    score += 20;
    reasons.push('urgent-timeline');
  } else if (t.includes('quarter') || t.includes('month')) {
    score += 12;
    reasons.push('mid-timeline');
  } else {
    score += 6;
    reasons.push('long-timeline');
  }
}

// Intent signal
if (bant.intent && String(bant.intent).length > 30) {
  score += 10;
  reasons.push('expressed-intent');
}

let temperature = 'cold';
if (score >= 70) temperature = 'hot';
else if (score >= 40) temperature = 'warm';

return [{
  json: {
    ...input,
    score,
    temperature,
    scoringReasons: reasons,
  },
}];

// Pick CRM target from env. Default pipedrive.
// Pick stage ID from temperature.

const input = $input.first().json;
const crmTarget = ($env.CRM_TARGET || 'pipedrive').toLowerCase();

const stageMap = {
  hot: $env.CRM_PIPELINE_HOT_ID || '1',
  warm: $env.CRM_PIPELINE_WARM_ID || '2',
  cold: $env.CRM_PIPELINE_COLD_ID || '3',
};

const stageId = stageMap[input.temperature] || stageMap.cold;

return [{
  json: {
    ...input,
    crmTarget,
    stageId,
  },
}];

// Normalize CRM response shape so downstream nodes do not care which CRM
// fired. Pull deal_id and deal_url where possible.

const input = $input.first();
const body = input.json || {};
const incoming = body;

// Pipedrive returns { success: true, data: { id, ... } }
// HubSpot returns { id, properties, ... }
// Salesforce returns { id, success, errors, ... }
let dealId = null;
let dealUrl = null;

if (incoming.data && incoming.data.id) {
  dealId = incoming.data.id;
} else if (incoming.id) {
  dealId = incoming.id;
}

return [{
  json: {
    ...incoming,
    dealId,
    dealUrl,
    crmSuccess: !!dealId,
  },
}];

// Fallback for downstream API failures (Pipedrive / HubSpot / Salesforce / Slack).
// Builds a structured error log and produces a graceful response so the form
// submitter sees a 200 instead of a hung request.

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const original = ($('Set CRM Target').first() && $('Set CRM Target').first().json) || {};

return [{
  json: {
    ok: false,
    fallback: true,
    submissionId: original.submissionId || 'unknown',
    crmTarget: original.crmTarget || 'unknown',
    stage: original.temperature || 'unknown',
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'CrmError',
    },
    receivedAt: original.receivedAt || new Date().toISOString(),
  },
}];
